import crypto from 'node:crypto'

// rawBody must be the exact request bytes (e.g. express.raw({ type: 'application/json' })).
export function verifySigmaWebhook(rawBody, signatureHeader, secret, toleranceSeconds = 300) {
  const fields = {}
  for (const pair of String(signatureHeader ?? '').split(',')) {
    const index = pair.indexOf('=')
    if (index > 0) fields[pair.slice(0, index).trim()] = pair.slice(index + 1).trim()
  }
  const timestamp = fields.t ?? ''
  const signature = fields.v1 ?? ''
  if (!/^\d+$/.test(timestamp) || !/^[a-f0-9]{64}$/.test(signature)) return false
  if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > toleranceSeconds) return false
  const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.`).update(rawBody).digest()
  return crypto.timingSafeEqual(expected, Buffer.from(signature, 'hex'))
}

