import hashlib
import hmac
import time

def verify_sigma_webhook(raw_body: bytes, signature_header: str, secret: str, tolerance_seconds: int = 300) -> bool:
    fields = {}
    for pair in (signature_header or '').split(','):
        key, sep, value = pair.strip().partition('=')
        if sep:
            fields[key] = value
    timestamp = fields.get('t', '')
    signature = fields.get('v1', '')
    if not (timestamp.isascii() and timestamp.isdigit()) or not signature:
        return False
    if abs(int(time.time()) - int(timestamp)) > tolerance_seconds:
        return False
    expected = hmac.new(secret.encode(), timestamp.encode() + b'.' + raw_body, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

