import (
    "crypto/hmac"
    "crypto/sha256"
    "encoding/hex"
    "strconv"
    "strings"
    "time"
)

// rawBody must be the exact request bytes (io.ReadAll(r.Body) before decoding).
func VerifySigmaWebhook(rawBody []byte, signatureHeader, secret string, tolerance time.Duration) bool {
    var timestamp, signature string
    for _, pair := range strings.Split(signatureHeader, ",") {
        key, value, ok := strings.Cut(strings.TrimSpace(pair), "=")
        if !ok {
            continue
        }
        switch key {
        case "t":
            timestamp = value
        case "v1":
            signature = value
        }
    }
    ts, err := strconv.ParseInt(timestamp, 10, 64)
    if err != nil || signature == "" {
        return false
    }
    if age := time.Since(time.Unix(ts, 0)); age > tolerance || age < -tolerance {
        return false
    }
    mac := hmac.New(sha256.New, []byte(secret))
    mac.Write([]byte(timestamp + "."))
    mac.Write(rawBody)
    return hmac.Equal([]byte(hex.EncodeToString(mac.Sum(nil))), []byte(signature))
}

